--
-- Table structure for table `configuraciones`
--

DROP TABLE IF EXISTS `configuraciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `configuraciones` (
  `id_config` int(11) NOT NULL AUTO_INCREMENT,
  `pac` varchar(50) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `version` varchar(20) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `ruta_timbrado` varchar(150) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `proveedor` varchar(50) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `usuario` varchar(100) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `palabra_paso` varchar(20) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `ruta_keys` varchar(150) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `predeterminado` tinyint(4) DEFAULT NULL,
  `ruta_pac` varchar(255) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `utilidades_pac` varchar(255) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `registro_cliente_pac` varchar(255) COLLATE utf8_spanish2_ci DEFAULT NULL,
  `cancelacion_pac` varchar(255) COLLATE utf8_spanish2_ci DEFAULT NULL,
