--
-- Table structure for table `facturas_emitidas`
--

DROP TABLE IF EXISTS `facturas_emitidas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `facturas_emitidas` (
  `id_factura` int(11) NOT NULL AUTO_INCREMENT,
  `numero_factura` varchar(20) DEFAULT NULL,
  `fecha_factura` datetime NOT NULL,
  `lugar_expedicion` varchar(10) DEFAULT NULL,
  `id_cliente_emisor` int(11) DEFAULT NULL,
  `rfc_emisor` varchar(20) NOT NULL,
  `id_cliente_receptor` int(11) NOT NULL,
  `rfc_receptor` varchar(255) DEFAULT NULL,
  `forma_pago_f` varchar(5) NOT NULL,
  `metodo_pago_f` varchar(5) DEFAULT NULL,
  `moneda_f` varchar(5) DEFAULT NULL,
  `uso_cfdi_f` varchar(10) DEFAULT NULL,
  `tipo_comprobante` varchar(5) DEFAULT NULL,
  `id_cliente_propietario` int(11) DEFAULT NULL,
  `tipo_impuesto` varchar(11) DEFAULT NULL,
  `subtotal` varchar(20) DEFAULT NULL,
  `impuesto` varchar(20) DEFAULT NULL,
  `total_venta` varchar(20) DEFAULT NULL,
  `saldo` varchar(20) DEFAULT NULL,
  `impuestos_retenidos` varchar(20) DEFAULT NULL,
  `impuestos_trasladados` varchar(20) DEFAULT NULL,
  `status_factura` tinyint(4) NOT NULL,
  `codigo_mf` varchar(250) DEFAULT NULL,
  `fecha_timbrado` datetime DEFAULT NULL,
  `val_iva_trasladado` varchar(20) DEFAULT NULL,
  `val_iva_retenido` varchar(20) DEFAULT NULL,
  `val_isr_retenido` varchar(20) DEFAULT NULL,
  `uuid` varchar(60) DEFAULT NULL,
  `certificado_no` varchar(60) DEFAULT NULL,
  `sello` text,
  `sello_sat` text,
  `certificado_sat` text,
  `cadena_original_sat` text,
  `mensaje_jason` text,
  `version_cfdi` varchar(10) DEFAULT NULL,
